# Standalone, stdlib-zero: no imports, no I/O, no floats. Witness embedded as a literal.
# Result: raise SystemExit(0) iff every property is exactly verified; SystemExit(1) otherwise.

def verify():
    w = {
        "num_vertices": 11,
        "edges": [[0,1],[1,2],[2,3],[3,4],[4,0],[5,1],[5,4],[6,0],[6,2],[7,1],[7,3],
                  [8,2],[8,4],[9,0],[9,3],[10,5],[10,6],[10,7],[10,8],[10,9]]
    }
    n = w["num_vertices"]
    if not isinstance(n, int) or n <= 0:
        return False
    E = set()
    for pair in w["edges"]:
        a, b = pair
        if not (isinstance(a, int) and isinstance(b, int)):
            return False
        if not (0 <= a < n and 0 <= b < n) or a == b:
            return False
        E.add((min(a, b), max(a, b)))
    if len(w["edges"]) != len(E):
        return False
    adj = [set() for _ in range(n)]
    for a, b in E:
        adj[a].add(b)
        adj[b].add(a)

    # 1. triangle-freeness, exact
    for a in range(n):
        for b in adj[a]:
            if b > a:
                for c in adj[b]:
                    if c in adj[a]:
                        return False

    # 2. independence number, exact exhaustive search
    def is_indep(s):
        for i in range(len(s)):
            for j in range(i + 1, len(s)):
                if s[j] in adj[s[i]]:
                    return False
        return True

    alpha = 0
    for r in range(n, 0, -1):
        found = False
        # combinations generated index-wise, no itertools
        idx = list(range(r))
        while True:
            if is_indep([idx[i] for i in range(r)]):
                found = True
                break
            i = r - 1
            while i >= 0 and idx[i] == n - r + i:
                i -= 1
            if i < 0:
                break
            idx[i] += 1
            for j in range(i + 1, r):
                idx[j] = idx[j - 1] + 1
        if found:
            alpha = r
            break
    if alpha != 5:
        return False

    # 3. chromatic number, exact backtracking, no recursion depth tricks
    def colorable(k):
        colors = [0] * n
        stack = []
        i = 0
        while True:
            if i == n:
                return True
            used = set()
            for j in adj[i]:
                if j < i:
                    used.add(colors[j])
            placed = False
            c = colors[i]
            while c < k:
                if c not in used:
                    colors[i] = c
                    stack.append(c)
                    placed = True
                    break
                c += 1
            if placed:
                i += 1
            else:
                colors[i] = 0
                if not stack:
                    return False
                i -= 1
                used_prev = set()
                for j in adj[i]:
                    if j < i:
                        used_prev.add(colors[j])
                c = stack.pop() + 1
                placed = False
                while c < k:
                    if c not in used_prev:
                        colors[i] = c
                        stack.append(c)
                        placed = True
                        break
                    c += 1
                if not placed:
                    colors[i] = 0
                    if not stack:
                        return False
                    i -= 1
                    # continue unwinding at top of loop
                    # (colors[i] currently stale; force retry path)
                    colors[i] = k  # sentinel to force the unplaced branch next pass
                    continue
        # unreachable

    chi = None
    for k in range(1, n + 1):
        if colorable(k):
            chi = k
            break
    if chi != 4:
        return False

    # 4. counting inequality chi >= ceil(N/alpha), exact integer arithmetic
    if chi * alpha < n:
        return False
    if chi < -(-n // alpha):
        return False
    return True

if verify():
    raise SystemExit(0)
else:
    raise SystemExit(1)
